		first.StatusCounts.Succeeded != 1 || first.StatusCounts.Failed != 2 {
		t.Fatalf("first counts = %+v", first.StatusCounts)
	}
	if first.RetryCountMin == nil || *first.RetryCountMin != 0 ||
